  var DL_IC   = '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v12"/><path d="M7 11l5 5 5-5"/><path d="M5 20h14"/></svg>';
  var REPLAY_IC = '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12a9 9 0 1 1-3-6.7"/><path d="M21 3v5h-5"/></svg>';

  // Restart every animation in an asset's <svg> from frame 0 (one-shots re-play, infinites re-sync).
  function replayAnimations(svg) {
    svg.classList.add('anim-off');
    void svg.getBoundingClientRect();   // force reflow so the "animation:none" takes effect
    svg.classList.remove('anim-off');
  }

  // "Nothing here — yet" -> "nothing-here-yet" for a friendly .svg filename
  function slugify(name) {
    return (name || 'asset').toLowerCase()
      .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'asset';
  }

  // Save a standalone .svg document (self-animating markup + XML prolog) to disk.
  function downloadSvg(markup, filename) {
    var doc = '<?xml version="1.0" encoding="UTF-8"?>\n' + markup;
    var blob = new Blob([doc], { type: 'image/svg+xml' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url; a.download = filename;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
  }

  function fallbackCopy(text) {
    var ta = document.createElement('textarea');
    ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
    document.body.appendChild(ta); ta.select();
    var ok = false; try { ok = document.execCommand('copy'); } catch (e) {}
    document.body.removeChild(ta); return ok;
  }

  document.querySelectorAll('.card').forEach(function (card) {
    var svg = card.querySelector('.stage svg');
    if (!svg) return;
    var name = (card.querySelector('.name') || {}).textContent || 'asset';

    // Replay control on the stage — re-runs the asset's animation for inspection.
    var stage = card.querySelector('.stage');
    if (stage) {
      var replay = document.createElement('button');
      replay.type = 'button';
      replay.className = 'replay-btn';
      replay.innerHTML = REPLAY_IC + '<span>Replay</span>';
      replay.setAttribute('aria-label', 'Replay the ' + name + ' animation');
      replay.addEventListener('click', function () { replayAnimations(svg); });
      stage.appendChild(replay);
    }

    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'copy-btn';
    btn.innerHTML = COPY_IC + '<span>Copy SVG</span>';
    btn.setAttribute('aria-label', 'Copy SVG markup for ' + name);

    btn.addEventListener('click', function () {
      var markup = buildSvg(svg);
      var done = function () {
        btn.classList.add('done');
        btn.innerHTML = DONE_IC + '<span>Copied!</span>';
        showToast('SVG copied — paste it anywhere');
        setTimeout(function () {
          btn.classList.remove('done');
          btn.innerHTML = COPY_IC + '<span>Copy SVG</span>';
        }, 1800);
      };
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(markup).then(done, function () {
          if (fallbackCopy(markup)) done(); else showToast('Copy failed — select manually');
        });
      } else {
        if (fallbackCopy(markup)) done(); else showToast('Copy failed — select manually');
      }
    });

    var dl = document.createElement('button');
    dl.type = 'button';
    dl.className = 'dl-btn';
    dl.innerHTML = DL_IC;
    dl.setAttribute('aria-label', 'Download ' + name + ' as an SVG file');
    dl.title = 'Download .svg';
    dl.addEventListener('click', function () {
      downloadSvg(buildSvg(svg), slugify(name) + '.svg');
      showToast('Downloaded ' + slugify(name) + '.svg');
    });

    var actions = document.createElement('div');
    actions.className = 'actions';
    actions.appendChild(btn);
    actions.appendChild(dl);
    card.querySelector('.body').appendChild(actions);
  });

  // ---- Journey-stage filtering ----
  var cards = Array.prototype.slice.call(document.querySelectorAll('.card'));
  var chips = Array.prototype.slice.call(document.querySelectorAll('.filterbar .chip'));
  var countEl = document.getElementById('fbCount');
  var emptyNote = document.getElementById('emptyNote');

  function applyFilter(filter) {
    var shown = 0;
    cards.forEach(function (card) {
      var match = filter === 'all' || card.getAttribute('data-cat') === filter;
      card.classList.toggle('hide', !match);
      if (match) shown++;
    });
    chips.forEach(function (chip) {
      chip.setAttribute('aria-pressed', String(chip.getAttribute('data-filter') === filter));
    });
    countEl.textContent = shown + (shown === 1 ? ' asset' : ' assets');
    emptyNote.style.display = shown === 0 ? 'block' : 'none';
  }

  chips.forEach(function (chip) {
    chip.addEventListener('click', function () { applyFilter(chip.getAttribute('data-filter')); });
  });

  // ---- Global motion toggle (freeze/resume all asset animations) ----
  var motionBtn = document.getElementById('motionToggle');
  if (motionBtn) {
    motionBtn.addEventListener('click', function () {
      var paused = document.body.classList.toggle('motion-paused');
      motionBtn.setAttribute('aria-pressed', String(paused));
      motionBtn.setAttribute('aria-label', paused ? 'Resume all asset animations' : 'Pause all asset animations');
    });
  }
})();
</script>
</body>

